    solution: 'class Noeud:\n    def __init__(self, valeur, suivant=None):\n        self.valeur = valeur\n        self.suivant = suivant\n\nclass Liste:\n    def __init__(self):\n        self.tete = None\n\n    def ajoute(self, x):\n        self.tete = Noeud(x, self.tete)\n\n    def en_liste(self):\n        res = []\n        n = self.tete\n        while n:\n            res.append(n.valeur)\n            n = n.suivant\n        return res',
